  const dmTexts=__DATA_MANAGEMENT_TEXTS__;
  Object.assign(state,{dmImport:'ready',dmArchiveOverwrite:false,dmTransfer:'ready'});
  function dmTask(title,subtitle,phase='ready',label='',value=.4,action='',preview=false){return `<div class="dm-task" data-file-state="${phase}"><div class="dm-task-heading">${btn(action||'dm-inert',`<span class="bc-menu-symbol">${icon(phase==='success'?'circle-check':phase==='partial'?'info':phase==='error'?'circle-alert':action==='dm-export'?'archive':action==='dm-import'?'folder-input':'file-up')}</span><span class="bc-menu-copy"><b>${esc(title)}</b>${subtitle?`<small>${esc(subtitle)}</small>`:''}</span>${phase==='running'?icon('loader-circle'):action&&!preview?icon('chevron-right'):''}`,title,'bc-menu-row',phase==='running'||!action?'disabled':'')}${preview&&phase==='ready'?btn('dm-preview',icon('eye'),dmTexts.attachmentPreview,'bc-icon'):''}</div>${['running','success'].includes(phase)?`<div class="dm-progress"><span>${esc(label||subtitle||title)}</span><progress max="1" ${value==null?'':`value="${value}"`}></progress></div>`:''}</div>`;}
  function dmImportTask(){const phase=state.dmImport;if(phase==='ready')return dmTask(dmTexts.mineImport,'','ready','','','leaf:'+dmTexts.mineImport);return dmTask(phase==='running'?dmTexts.mineImportProgressTitle:dmTexts.mineImportCompleteTitle,phase==='success'?dmTexts.mineImportCompleteAllSuccess:phase==='partial'?'成功 8，失败 2':'已处理4/10 · 成功3 · 失败1',phase,phase==='success'?dmTexts.mineImportCompleteAllSuccess:'已处理4/10',phase==='running' ? .4 : 1);}
  dataManagement=function(){return `${subhead(dmTexts.dataManagementPageTitle)}<p class="dm-hint">${esc(dmTexts.dataManagementAttachmentHint)}</p>${sectionLabel(dmTexts.v4DataBills)}${surface(dmImportTask()+menuRow('leaf:导出数据','file-down',dmTexts.mineExport),'bc-menu-card')}${sectionLabel(dmTexts.v4DataCategories)}${menuCard([['leaf:分类管理','shapes',dmTexts.mineCategoryManagement,dmTexts.mineCategoryManagementSubtitle],['leaf:分类迁移','arrow-left-right',dmTexts.mineCategoryMigration,dmTexts.mineCategoryMigrationSubtitle],['leaf:标签管理','tags',dmTexts.tagManageTitle,dmTexts.tagManageSubtitle]])}${sectionLabel(dmTexts.v4DataConfiguration)}${menuCard([['leaf:配置导入导出','file-cog',dmTexts.configImportExportTitle,dmTexts.configImportExportSubtitle],['leaf:存储空间管理','hard-drive',dmTexts.storageManagementTitle,dmTexts.storageManagementSubtitle],['leaf:数据清理','brush-cleaning',dmTexts.maintenanceOrphanCleanupTitle,dmTexts.maintenanceOrphanCleanupSubtitle]])}${sectionLabel(dmTexts.v4DataAttachments)}${surface(menuRow('dm-preview','eye',dmTexts.attachmentPreview)+dmTask(dmTexts.attachmentExportTitle,dmTexts.attachmentExportSubtitle,state.dmTransfer==='export'?'running':'ready','附件5 · 自定义图标2 · 已处理4/7',4/7,'dm-export',true)+dmTask(dmTexts.attachmentImportTitle,dmTexts.attachmentImportSubtitle,state.dmTransfer==='import'?'running':'ready','已处理4/7',4/7,'dm-import'),'bc-menu-card')}`;};
  function dmArchive(){return `<div class="dm-archive"><div class="bc-row">${icon('archive')}<b>beecount_attachments_20261025.tar.gz</b></div><p>5 张附件 · 2026-10-25 09:41<br>自定义图标: 2 个<br>包含头像</p><h4>${esc(dmTexts.attachmentImportConflictStrategy)}</h4>${[[false,dmTexts.attachmentImportConflictSkip],[true,dmTexts.attachmentImportConflictOverwrite]].map(([value,label])=>btn('dm-strategy:'+value,`<span class="dm-radio">${state.dmArchiveOverwrite===value?'●':'○'}</span>${esc(label)}`,label,'dm-choice',`role="radio" aria-checked="${state.dmArchiveOverwrite===value}"`)).join('')}</div><div class="dm-dialog-actions">${btn('r-close',dmTexts.commonCancel,dmTexts.commonCancel,'bc-secondary')}${btn('dm-archive-preview',dmTexts.attachmentPreview,dmTexts.attachmentPreview,'bc-secondary')}${btn('dm-confirm',dmTexts.attachmentStartImport,dmTexts.attachmentStartImport,'bc-primary')}</div>`;}
  rSpecs['attachment-import-confirm']={title:dmTexts.attachmentImportTitle,host:'data',kind:'dialog'};
  fDefine('attachment-import-confirm','附件导入 · 原归档确认弹窗','导入导出与维护','settings/data_management_page.dart',dmArchive);
  const dmFlows=[['data-import-running','数据管理 · 后台导入中','running','ready'],['data-import-success','数据管理 · 原导入完成','success','ready'],['data-import-partial','数据管理 · 部分失败','partial','ready'],['attachment-export-progress','数据管理 · 附件导出进度','ready','export'],['attachment-import-progress','数据管理 · 附件导入进度','ready','import']];
  for(const[key,title,phase,transfer]of dmFlows)fDefine(key,title,'导入导出与维护','settings/data_management_page.dart',()=>{state.dmImport=phase;state.dmTransfer=transfer;return dataManagement();});
  fDefs['attachment-transfer'].body=()=>`${surface(`<h3>附件与自定义图标</h3><p class="bc-small">TAR.GZ 归档 · 保留账单关联、头像与分类图标</p>`)}${btn('dm-preview',dmTexts.attachmentPreview,dmTexts.attachmentPreview,'bc-secondary')}${fCTA('dm-export',dmTexts.attachmentExportTitle)}${fCTA('dm-import',dmTexts.attachmentImportTitle)}`;
  const dmPrevRender=fRender;fRender=function(key){const item=dmFlows.find(x=>x[0]===key);if(item){state.dmImport=item[2];state.dmTransfer=item[3];return dataManagement();}return dmPrevRender(key);};
  const dmPrevModal=rModalBody;rModalBody=function(key){return key==='attachment-import-confirm'?dmArchive():dmPrevModal(key);};
  const dmGroup=document.createElement('optgroup');dmGroup.label='数据管理 · 原任务与归档';for(const[key,title]of [['attachment-import-confirm','附件导入 · 原确认弹窗'],...dmFlows])dmGroup.appendChild(new Option(title,'flow-'+key));picker.appendChild(dmGroup);
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el?.dataset.action.startsWith('dm-'))return;event.preventDefault();event.stopImmediatePropagation();const[action,value]=el.dataset.action.split(':');if(action==='dm-import'){state.dmArchiveOverwrite=false;rOpenModal('attachment-import-confirm');}else if(action==='dm-strategy'){state.dmArchiveOverwrite=value==='true';rBuildModal();}else if(action==='dm-preview'||action==='dm-archive-preview'){if(state.rModal)rClose();state.page=action==='dm-archive-preview'?'flow-attachment-library-archive':'flow-attachment-library';render();}else if(action==='dm-confirm'){rClose();state.dmTransfer='import';state.page='data';render();}else if(action==='dm-export'){state.dmTransfer='export';state.page='data';render();}},true);
